        try:
            row = self.billing.insert("credit_notes", {
                "account_id": account_id, "invoice_id": invoice_id, "line_ids": [line_id],
                "amount_cents": int(amount_cents), "reason": "duplicate", "memo": memo or "",
            })
        except BillingError as error:
